export function parseSubjectType(s: string): SubjectType {
  if (!s) {
    return SubjectType.UNSPECIFIED;
  }
  switch (s.toLowerCase()) {
    case "service":
      return SubjectType.SERVICE;
    case "api":
      return SubjectType.API;
    case "workload":
      return SubjectType.WORKLOAD;
    case "agent":
      return SubjectType.AGENT;
    default:
      throw newErrMissingInvalidData(undefined, `Invalid subjecttype: ${s}`);
  }
}
export function parseSubjectTypes(s: string): SubjectType[] {
  if (!s) {
    return [];
  }
  return s
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part !== "")
    .map((part) => parseSubjectType(part));
}
export function subjectTypeToString(v: SubjectType): string {
  switch (v) {
    case SubjectType.SERVICE:
      return "service";
    case SubjectType.API:
      return "api";
    case SubjectType.WORKLOAD:
      return "workload";
    case SubjectType.AGENT:
      return "agent";
    default:
      return "";
  }
}

